//Project Filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".project-card");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  const normalize = (s) =>
    (s || "")
      .toString()
      .toLowerCase()
      .trim()
      .replace(/&/g, "en")
      .replace(/[^\w\s-]/g, "")
      .replace(/\s+/g, " ");

  const parseValues = (raw) =>
    (raw || "")
      .split(/,|•|\n|\r|\t/gi)
      .map(normalize)
      .filter(Boolean);

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => normalize(el.getAttribute("data-filter-value")))
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  const projectData = Array.from(items).map((item) => {
    const themes = parseValues(item.getAttribute("data-project-themes"));
    const status = parseValues(item.getAttribute("data-project-status"));

    return {
      item,
      themes,
      status
    };
  });

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeThemes = getActive("themes");
    const activeStatus = getActive("status");

    projectData.forEach(({ item, themes, status }) => {
      const show =
        matches(themes, activeThemes) &&
        matches(status, activeStatus);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

//Magnetic Button
document.addEventListener("DOMContentLoaded", () => {
  initMagneticButtons();
});

function initMagneticButtons() {
  const buttons = document.querySelectorAll(".magnetic_cta");

  buttons.forEach((button) => {
    const inner = button.querySelector(".magnetic_cta_inner");
    if (!inner) return;

    let bounds = null;

    function updateBounds() {
      bounds = button.getBoundingClientRect();
    }

    function handleMove(event) {
      if (!bounds) updateBounds();

      const relX = event.clientX - bounds.left;
      const relY = event.clientY - bounds.top;

      const centerX = bounds.width / 2;
      const centerY = bounds.height / 2;

      const moveX = relX - centerX;
      const moveY = relY - centerY;
      
      gsap.to(button, {
        x: moveX * 0.18,
        y: moveY * 0.18,
        duration: 0.22,
        ease: "power3.out",
        overwrite: true
      });
   
      gsap.to(inner, {
        x: moveX * 0.22,
        y: moveY * 0.22,
        duration: 0.28,
        ease: "power3.out",
        overwrite: true
      });
    }

    function handleEnter() {
      updateBounds();
    }

    function handleLeave() {
      gsap.to(button, {
        x: 0,
        y: 0,
        duration: 0.45,
        ease: "elastic.out(1, 0.4)",
        overwrite: true
      });

      gsap.to(inner, {
        x: 0,
        y: 0,
        duration: 0.55,
        ease: "elastic.out(1, 0.35)",
        overwrite: true
      });
    }

    button.addEventListener("mouseenter", handleEnter);
    button.addEventListener("mousemove", handleMove);
    button.addEventListener("mouseleave", handleLeave);
    window.addEventListener("resize", updateBounds);
  });
}

//Page transition
function initShutterPageTransition() {
  const defaultRows = 6;
  const defaultDuration = 0.43;
  const defaultStagger = 0.075;
  const defaultEase = "expo.inOut";

  const homepageIntroRows = 6;
  const homepageIntroDuration = 0.7;
  const homepageIntroStagger = 0.1;
  const homepageIntroEase = "expo.inOut";

  const transitionFlagKey = "shutter_transition";
  const transitionColorsKey = "shutter_transition_colors";
  const homepageIntroSeenKey = "homepage_intro_seen";

  const colorPalette = [
    "#06246f",
    "#d7d86a",
    "#6b4a00",
    "#8b9444",
    "#d9be72",
    "#F09A3A",
    "#1d1d1d"
  ];

  const overlay = document.querySelector("[data-page-shutter]");
  const panel = document.querySelector("[data-page-shutter-panel]");

  if (!overlay || !panel) return null;

  function createRow(color) {
    const row = document.createElement("div");
    row.classList.add("page_shutter_row");
    row.style.backgroundColor = color;
    return row;
  }

  function shuffleArray(array) {
    const copy = [...array];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }

  function generateRowColors(rowCount) {
    if (!colorPalette.length) return Array(rowCount).fill("#000000");
    if (colorPalette.length === 1) return Array(rowCount).fill(colorPalette[0]);

    const colors = [];
    let lastColor = null;
    let pool = shuffleArray(colorPalette);

    for (let i = 0; i < rowCount; i++) {
      if (!pool.length) {
        pool = shuffleArray(colorPalette);
      }

      let color = pool.find((item) => item !== lastColor);

      if (!color) color = pool[0];

      const index = pool.indexOf(color);
      if (index > -1) {
        pool.splice(index, 1);
      }

      colors.push(color);
      lastColor = color;
    }

    return colors;
  }

  function saveTransitionColors(colors) {
    sessionStorage.setItem(transitionColorsKey, JSON.stringify(colors));
  }

  function getSavedTransitionColors() {
    const raw = sessionStorage.getItem(transitionColorsKey);
    if (!raw) return null;

    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : null;
    } catch {
      return null;
    }
  }

  function clearSavedTransitionColors() {
    sessionStorage.removeItem(transitionColorsKey);
  }

  function buildRows(colors, rowCount) {
    panel.innerHTML = "";

    const targetCount = rowCount || defaultRows;
    const rowColors =
      Array.isArray(colors) && colors.length
        ? colors.slice(0, targetCount)
        : generateRowColors(targetCount);

    while (rowColors.length < targetCount) {
      rowColors.push(colorPalette[rowColors.length % colorPalette.length] || "#000000");
    }

    const fragment = document.createDocumentFragment();

    for (let i = 0; i < targetCount; i++) {
      const row = createRow(rowColors[i]);
      fragment.appendChild(row);
    }

    panel.appendChild(fragment);
    return Array.from(panel.children);
  }

  function ensureRowsExist(colors, rowCount) {
    if (panel.children.length) return Array.from(panel.children);
    return buildRows(colors, rowCount);
  }

  function cover() {
    const rowColors = generateRowColors(defaultRows);
    saveTransitionColors(rowColors);

    const rows = buildRows(rowColors, defaultRows);

    return gsap
      .timeline()
      .set(overlay, { visibility: "visible", pointerEvents: "auto" })
      .set(rows, {
        scaleY: 0,
        transformOrigin: "bottom center"
      })
      .to(rows, {
        scaleY: 1,
        duration: defaultDuration,
        stagger: { each: defaultStagger, from: "end" },
        ease: defaultEase
      });
  }

  function reveal() {
    const savedColors = getSavedTransitionColors();
    const rows = ensureRowsExist(savedColors, defaultRows);

    return gsap
      .timeline()
      .set(overlay, { visibility: "visible", pointerEvents: "auto" })
      .set(rows, {
        scaleY: 1,
        transformOrigin: "top center"
      })
      .to(rows, {
        scaleY: 0,
        duration: defaultDuration,
        stagger: { each: defaultStagger, from: "end" },
        ease: defaultEase
      })
      .set(overlay, { pointerEvents: "none", visibility: "hidden" })
      .call(() => {
        document.documentElement.classList.remove("is_transitioning");
        clearSavedTransitionColors();
      });
  }

  function playHomepageIntro() {
    const introColors = generateRowColors(homepageIntroRows);
    const rows = buildRows(introColors, homepageIntroRows);

    return gsap
      .timeline()
      .set(overlay, { visibility: "visible", pointerEvents: "auto" })
      .set(rows, {
        scaleY: 1,
        transformOrigin: "top center"
      })
      .to(rows, {
        scaleY: 0,
        duration: homepageIntroDuration,
        stagger: { each: homepageIntroStagger, from: "end" },
        ease: homepageIntroEase
      })
      .set(overlay, { pointerEvents: "none", visibility: "hidden" })
      .call(() => {
        document.documentElement.classList.remove("is_transitioning");
        sessionStorage.setItem(homepageIntroSeenKey, "true");
      });
  }

  function resetToIdle() {
    document.documentElement.classList.remove("is_transitioning");
    gsap.set(overlay, { pointerEvents: "none", visibility: "hidden" });
  }

  function isHomepage() {
    const path = window.location.pathname;
    return path === "/" || path === "/index.html";
  }

  function hasSeenHomepageIntro() {
    return sessionStorage.getItem(homepageIntroSeenKey) === "true";
  }

  return {
    cover,
    reveal,
    playHomepageIntro,
    resetToIdle,
    isHomepage,
    hasSeenHomepageIntro,
    transitionFlagKey
  };
}

document.addEventListener("DOMContentLoaded", () => {
  const shutter = initShutterPageTransition();
  if (!shutter) return;

  const navEntry = performance.getEntriesByType("navigation")[0];
  const isBackForwardNavigation = navEntry && navEntry.type === "back_forward";
  const shouldRevealFromLink =
    sessionStorage.getItem(shutter.transitionFlagKey) === "true";

  if (shouldRevealFromLink) {
    sessionStorage.removeItem(shutter.transitionFlagKey);
    shutter.reveal();
  } else if (isBackForwardNavigation) {
    shutter.reveal();
  } else if (shutter.isHomepage() && !shutter.hasSeenHomepageIntro()) {
    document.documentElement.classList.add("is_transitioning");
    shutter.playHomepageIntro();
  } else {
    shutter.resetToIdle();
  }

  document.addEventListener("click", (event) => {
    const link = event.target.closest("a[href]");
    if (!link) return;

    const href = link.getAttribute("href");
    if (!href) return;

    const isAnchor = href.startsWith("#");
    const isMailto = href.startsWith("mailto:");
    const isTel = href.startsWith("tel:");
    const isJavascript = href.startsWith("javascript:");
    const isBlank = link.target === "_blank";
    const isDownload = link.hasAttribute("download");
    const isExternal = link.origin !== window.location.origin;

    if (
      isAnchor ||
      isMailto ||
      isTel ||
      isJavascript ||
      isBlank ||
      isDownload ||
      isExternal
    ) {
      return;
    }

    event.preventDefault();
    sessionStorage.setItem(shutter.transitionFlagKey, "true");
    document.documentElement.classList.add("is_transitioning");

    shutter.cover().eventCallback("onComplete", () => {
      window.location.href = href;
    });
  });
});

window.addEventListener("pageshow", (event) => {
  if (!event.persisted) return;

  const shutter = initShutterPageTransition();
  if (!shutter) return;

  shutter.reveal();
});

// Lenis
gsap.registerPlugin(ScrollTrigger);

  const lenis = new Lenis({
    lerp: 0.1,
    wheelMultiplier: 0.8,
    smoothWheel: true,
    smoothTouch: true
  });

  lenis.on('scroll', ScrollTrigger.update);

  gsap.ticker.add((time) => {
    lenis.raf(time * 1000);
  });

  gsap.ticker.lagSmoothing(0);

  ScrollTrigger.addEventListener("refresh", () => lenis.resize());
  ScrollTrigger.refresh();

function initDynamicCurrentYear() {  
  const currentYear = new Date().getFullYear();
  const currentYearElements = document.querySelectorAll('[data-current-year]');
  currentYearElements.forEach(currentYearElement => {
    currentYearElement.textContent = currentYear;
  });
}

// Initialize Dynamic Current Year
document.addEventListener('DOMContentLoaded', () => {
  initDynamicCurrentYear();
});

// Swiper
document.addEventListener("DOMContentLoaded", function () {
  document.querySelectorAll(".agenda-swiper").forEach(function (slider) {
    const swiperEl = slider.querySelector(".swiper");
    const nextBtn = slider.querySelector(".agenda-next");
    const prevBtn = slider.querySelector(".agenda-prev");

    if (!swiperEl) return;

    swiperEl.setAttribute("tabindex", "0");

    new Swiper(swiperEl, {
      slidesPerView: 3.5,
      spaceBetween: 16,
      speed: 775,
      snapToSlideEdge: true,

      navigation: {
        nextEl: nextBtn,
        prevEl: prevBtn,
      },

      keyboard: {
        enabled: true,
        onlyInViewport: true,
      },

      breakpoints: {
        0: { slidesPerView: 1.25, spaceBetween: 8, snapToSlideEdge: true },
        768: { slidesPerView: 2.25, spaceBetween: 12, snapToSlideEdge: true },
        1200: { slidesPerView: 2.5, spaceBetween: 16, snapToSlideEdge: true },
        1440: { slidesPerView: 3.25, spaceBetween: 16, snapToSlideEdge: true },
      },
    });
  });
});

// FAQ
document.addEventListener("click", (e) => {
  const trigger = e.target.closest(".faq_item_inner");
  if (!trigger) return;

  const item = trigger.closest(".faq_item");
  if (!item) return;

  const answer = item.querySelector(".faq_answer_wrapper");
  if (!answer) return;

  const isOpen = item.classList.contains("is-open");

  document.querySelectorAll(".faq_item.is-open").forEach((openItem) => {
    if (openItem === item) return;
    openItem.classList.remove("is-open");
    const openAnswer = openItem.querySelector(".faq_answer_wrapper");
    if (openAnswer) openAnswer.style.maxHeight = "0px";
  });

  if (isOpen) {
    item.classList.remove("is-open");
    answer.style.maxHeight = "0px";
  } else {
    item.classList.add("is-open");
    answer.style.maxHeight = answer.scrollHeight + "px";
  }
});

