//Agenda filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".card_item");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => (el.getAttribute("data-filter-value") || "").toLowerCase().trim())
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  function getTimeTags(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startOfEventDay = new Date(eventDate.getFullYear(), eventDate.getMonth(), eventDate.getDate());

    const day = startOfToday.getDay();
    const mondayOffset = day === 0 ? -6 : 1 - day;

    const startOfWeek = new Date(startOfToday);
    startOfWeek.setDate(startOfToday.getDate() + mondayOffset);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 7);

    const startOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth(), 1);
    const endOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth() + 1, 1);

    const tags = [];

    if (startOfEventDay >= startOfWeek && startOfEventDay < endOfWeek) tags.push("week");
    if (startOfEventDay >= startOfMonth && startOfEventDay < endOfMonth) tags.push("month");
    if (startOfEventDay >= endOfMonth) tags.push("future");

    return tags;
  }

  function getSeasonTag(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const month = eventDate.getMonth() + 1;

    if (month === 12 || month === 1 || month === 2) return ["winter"];
    if (month >= 3 && month <= 5) return ["lente"];
    if (month >= 6 && month <= 8) return ["zomer"];
    return ["herfst"];
  }

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeTime = getActive("time");
    const activeSeason = getActive("season");

    items.forEach((item) => {
      const eventDate = item.getAttribute("data-event-date");
      const itemTime = getTimeTags(eventDate);
      const itemSeason = getSeasonTag(eventDate);

      const show = matches(itemTime, activeTime) && matches(itemSeason, activeSeason);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

// Search
document.addEventListener("DOMContentLoaded", () => {
  const triggers = document.querySelectorAll(".search_icon");
  const modal = document.querySelector(".search_modal");

  if (!triggers.length || !modal || typeof gsap === "undefined") return;

  let isOpen = false;
  let isAnimating = false;

  gsap.set(modal, {
    display: "none",
    opacity: 0,
    y: -8
  });

  function openModal() {
    if (isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = true;

    gsap.set(modal, { display: "flex" });

    gsap.to(modal, {
      opacity: 1,
      y: 0,
      duration: 0.22,
      ease: "power2.out",
      onComplete: () => {
        isAnimating = false;
        const input = modal.querySelector("input, .w-input");
        if (input) input.focus();
      }
    });
  }

  function closeModal() {
    if (!isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = false;

    gsap.to(modal, {
      opacity: 0,
      y: -8,
      duration: 0.18,
      ease: "power2.in",
      onComplete: () => {
        gsap.set(modal, { display: "none" });
        isAnimating = false;
      }
    });
  }

  triggers.forEach((trigger) => {
    trigger.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      isOpen ? closeModal() : openModal();
    });
  });
  
  const closeTriggers = document.querySelectorAll(".close_search_icon");

closeTriggers.forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    closeModal();
  });
});

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      closeModal();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal();
    }
  });

  document.addEventListener("click", (e) => {
    const clickedTrigger = e.target.closest(".search_icon");
    const clickedInsideModal = e.target.closest(".search_modal");

    if (!clickedTrigger && !clickedInsideModal && isOpen) {
      closeModal();
    }
  });
});

// SplitText animation
gsap.registerPlugin(ScrollTrigger, SplitText)
  
function initHighlightText(){

  let splitHeadingTargets = document.querySelectorAll("[data-highlight-text]")
  splitHeadingTargets.forEach((heading) => {
    
    const scrollStart = heading.getAttribute("data-highlight-scroll-start") || "top 90%"
    const scrollEnd = heading.getAttribute("data-highlight-scroll-end") || "center 40%"
    const fadedValue = heading.getAttribute("data-highlight-fade") || 0.2 // Opacity of letter
    const staggerValue =  heading.getAttribute("data-highlight-stagger") || 0.1 // Smoother reveal
    
    new SplitText(heading, {
      type: "words, chars",
      autoSplit: true,
      onSplit(self) {
        let ctx = gsap.context(() => {
          let tl = gsap.timeline({
            scrollTrigger: {
              scrub: true,
              trigger: heading, 
              start: scrollStart,
              end: scrollEnd,
            }
          })
          tl.from(self.chars,{
            autoAlpha: fadedValue,
            stagger: staggerValue,
            ease: "linear"
          })
        });
        return ctx; // return our animations so GSAP can clean them up when onSplit fires
      }
    });    
  });
}

// Initialize Highlight Text on Scroll
document.addEventListener("DOMContentLoaded", () =>{
  initHighlightText();
});

// Navbar logic
function normalizeNavValue(value) {
  return (value || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/_/g, "-");
}

function isActuallyVisible(element) {
  return !!(element && (element.offsetWidth || element.offsetHeight || element.getClientRects().length));
}

function getActiveNavbar() {
  const activeNavFromDataset = normalizeNavValue(document.documentElement.dataset.activeNav || "");

  if (activeNavFromDataset) {
    const matchingNavbars = [
      ...document.querySelectorAll(`.navbar[data-nav="${activeNavFromDataset}"]`)
    ];

    return matchingNavbars.find(isActuallyVisible) || matchingNavbars[0] || null;
  }

  return [...document.querySelectorAll(".navbar[data-nav]")].find(isActuallyVisible) || null;
}

document.addEventListener("DOMContentLoaded", () => {
  const navbar = getActiveNavbar();

  if (!navbar) {
    console.warn("No active navbar found");
    return;
  }

  initNavbarOverlapScroll(navbar);
  initTabbarDropdown(navbar);
  initMegaMenu(navbar);
});


// =============================
// NAVBAR SCROLL (DESKTOP ONLY)
// =============================
function initNavbarOverlapScroll(navbar) {
  const navbarWrapper = navbar.querySelector(".navbar_wrapper");
  const tabbar = navbar.querySelector(".tabbar_wrapper");
  const nav = navbar.querySelector(".nav_wrapper");

  if (!navbarWrapper || !tabbar || !nav) return;

  let tabbarHeight = 0;
  let navHeight = 0;
  let fullHeight = 0;

  let isCollapsed = false;
  let lastScrollY = window.scrollY;
  let scrollAccumulator = 0;

  const mobileBreakpoint = 991;
  const threshold = 30;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function updateMeasurements() {
    if (!isActuallyVisible(navbar)) return;

    tabbarHeight = tabbar.offsetHeight;
    navHeight = nav.offsetHeight;
    fullHeight = tabbarHeight + navHeight;

    if (isMobile()) {
      gsap.set(tabbar, { y: 0, opacity: 1 });
      gsap.set(navbarWrapper, { height: "auto" });
    } else {
      gsap.set(navbarWrapper, {
        height: isCollapsed ? navHeight : fullHeight
      });
    }
  }

  function collapse() {
    if (isCollapsed || isMobile()) return;
    isCollapsed = true;

    gsap.to(navbarWrapper, {
      height: navHeight,
      duration: 1.2,
      ease: "expo.out"
    });

    gsap.to(tabbar, {
      y: -tabbarHeight,
      opacity: 0,
      duration: 0.6,
      ease: "expo.out"
    });
  }

  function expand() {
    if (!isCollapsed || isMobile()) return;
    isCollapsed = false;

    gsap.to(navbarWrapper, {
      height: fullHeight,
      duration: 1.2,
      ease: "expo.out"
    });

    gsap.to(tabbar, {
      y: 0,
      opacity: 1,
      duration: 0.6,
      ease: "expo.out"
    });
  }

  function onScroll() {
    if (isMobile()) return;

    const currentScrollY = window.scrollY;
    const delta = currentScrollY - lastScrollY;

    if (currentScrollY <= 10) {
      expand();
      scrollAccumulator = 0;
      lastScrollY = currentScrollY;
      return;
    }

    scrollAccumulator += delta;

    if (scrollAccumulator > threshold) {
      collapse();
      scrollAccumulator = 0;
    }

    if (scrollAccumulator < -threshold) {
      expand();
      scrollAccumulator = 0;
    }

    lastScrollY = currentScrollY;
  }

  window.addEventListener("resize", updateMeasurements);
  window.addEventListener("scroll", onScroll, { passive: true });

  updateMeasurements();
}


// =============================
// TABBAR (UNCHANGED)
// =============================
function initTabbarDropdown(navbar) {
  const wrapper = navbar.querySelector(".tabbar_wrapper");
  if (!wrapper) return;

  // keep your current working version — no change needed
}


// =============================
// MEGA MENU (DESKTOP + MOBILE)
// =============================
function initMegaMenu(navbar) {
  const mobileBreakpoint = 991;

  const megaMenu = navbar.querySelector(".mega_menu_wrapper");
  const overlay = navbar.querySelector(".page_overlay");
  const triggers = [...navbar.querySelectorAll("[data_menu_trigger]")];
  const panels = [...navbar.querySelectorAll("[data_menu_panel]")];

  if (!megaMenu || !triggers.length || !panels.length || typeof gsap === "undefined") return;

  let activeKey = null;
  let currentPanel = null;
  let isAnimating = false;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function getPanel(key) {
    return panels.find((p) => p.getAttribute("data_menu_panel") === key);
  }

  function resetAll() {
    panels.forEach((panel) => {
      gsap.set(panel, { display: "none", opacity: 0, y: 0 });
    });

    gsap.set(megaMenu, {
      height: 0,
      pointerEvents: "none"
    });

    if (overlay) {
      gsap.set(overlay, { opacity: 0, pointerEvents: "none" });
    }

    activeKey = null;
    currentPanel = null;
    isAnimating = false;
  }

  // =====================
  // DESKTOP
  // =====================
  function openDesktop(key) {
    const next = getPanel(key);
    if (!next || isAnimating) return;

    const old = currentPanel;
    currentPanel = next;
    activeKey = key;
    isAnimating = true;

    gsap.set(next, { display: "flex", opacity: 0, y: 16 });

    const height = next.offsetHeight;

    const tl = gsap.timeline({
      onComplete: () => {
        if (old && old !== next) gsap.set(old, { display: "none" });
        isAnimating = false;
      }
    });

    tl.to(megaMenu, { height, duration: 0.4, ease: "power3.out" }, 0);

    if (old && old !== next) {
      tl.to(old, { opacity: 0, duration: 0.2 }, 0);
    }

    tl.to(next, { opacity: 1, y: 0, duration: 0.3 }, 0.05);

    if (overlay) {
      tl.to(overlay, { opacity: 1, pointerEvents: "auto", duration: 0.2 }, 0);
    }
  }

  function closeDesktop() {
    if (!currentPanel || isAnimating) return;

    const panel = currentPanel;
    currentPanel = null;
    isAnimating = true;

    const tl = gsap.timeline({
      onComplete: () => {
        resetAll();
      }
    });

    tl.to(panel, { opacity: 0, duration: 0.2 }, 0);
    tl.to(megaMenu, { height: 0, duration: 0.3 }, 0.05);

    if (overlay) {
      tl.to(overlay, { opacity: 0, duration: 0.2 }, 0);
    }
  }

  // =====================
  // MOBILE (OVERLAY STYLE)
  // =====================
  function openMobile(key) {
    const next = getPanel(key);
    if (!next || isAnimating) return;

    if (currentPanel === next) {
      closeMobile();
      return;
    }

    const old = currentPanel;
    currentPanel = next;
    activeKey = key;
    isAnimating = true;

    gsap.set(next, { display: "flex", opacity: 0, y: -12 });

    const height = next.offsetHeight;

    const tl = gsap.timeline({
      onComplete: () => {
        if (old && old !== next) gsap.set(old, { display: "none" });
        megaMenu.style.pointerEvents = "auto";
        isAnimating = false;
      }
    });

    tl.to(megaMenu, { height, duration: 0.28, ease: "power2.out" }, 0);

    if (old && old !== next) {
      tl.to(old, { opacity: 0, duration: 0.15 }, 0);
    }

    tl.to(next, { opacity: 1, y: 0, duration: 0.25 }, 0.05);

    if (overlay) {
      tl.to(overlay, { opacity: 1, pointerEvents: "auto", duration: 0.2 }, 0);
    }
  }

  function closeMobile() {
    if (!currentPanel || isAnimating) return;

    const panel = currentPanel;
    currentPanel = null;
    isAnimating = true;

    const tl = gsap.timeline({
      onComplete: () => resetAll()
    });

    tl.to(panel, { opacity: 0, y: -10, duration: 0.2 }, 0);
    tl.to(megaMenu, { height: 0, duration: 0.25 }, 0.02);

    if (overlay) {
      tl.to(overlay, { opacity: 0, duration: 0.2 }, 0);
    }
  }

  // =====================
  // EVENTS
  // =====================
  triggers.forEach((trigger) => {
    const key = trigger.getAttribute("data_menu_trigger");

    trigger.addEventListener("mouseenter", () => {
      if (!isMobile()) openDesktop(key);
    });

    trigger.addEventListener("click", (e) => {
      if (!isMobile()) return;
      e.preventDefault();
      openMobile(key);
    });
  });

  document.addEventListener("click", (e) => {
    if (!navbar.contains(e.target)) {
      isMobile() ? closeMobile() : closeDesktop();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      isMobile() ? closeMobile() : closeDesktop();
    }
  });

  window.addEventListener("resize", resetAll);

  resetAll();
}
